const body = $input.first().json.body || $input.first().json;
let rawClaims = [];
if (Array.isArray(body.claims)) {
  rawClaims = body.claims;
} else if (body.claim || body.claim_text) {
  rawClaims = [{
    claim_id: body.request_id || "claim_001",
    claim_text: body.claim || body.claim_text,
    claim_type: "FACTUAL_CLAIM",
    domain: body.domain || "general",
    entities: Array.isArray(body.entities) ? body.entities : [],
    search_queries: Array.isArray(body.search_queries) ? body.search_queries : []
  }];
}

const validClaims = [];
for (const c of rawClaims) {
  if (!c || typeof c !== 'object') continue;
  if (!c.claim_id || typeof c.claim_id !== 'string') continue;
  if (!c.claim_text || typeof c.claim_text !== 'string' || !c.claim_text.trim()) continue;
  if (c.claim_type && c.claim_type !== 'FACTUAL_CLAIM') continue;
  validClaims.push({
    claim_id: c.claim_id.trim(),
    claim_text: c.claim_text.trim(),
    claim_type: 'FACTUAL_CLAIM',
    domain: (c.domain || body.domain || 'general').toLowerCase(),
    entities: Array.isArray(c.entities) ? c.entities : [],
    search_queries: Array.isArray(c.search_queries) && c.search_queries.length > 0 ? c.search_queries : [c.claim_text.trim()],
    time_sensitive: !!c.time_sensitive,
    request_id: body.request_id || c.claim_id
  });
}

return validClaims.map(c => ({ json: c }));

const items = $input.all();
const rawEvidence = [];
for (const item of items) {
  const d = item.json;
  const cid = d.claim_id || 'claim_001';
  const passages = Array.isArray(d.passages) ? d.passages : (Array.isArray(d.results) ? d.results : [d]);
  for (const p of passages) {
    if (!p) continue;
    rawEvidence.push({
      claim_id: cid,
      evidence_id: p.evidence_id || p.source_id || `ev_${Math.random().toString(36).substr(2, 9)}`,
      title: p.title || p.source_title || 'Retrieved Document',
      url: p.url || p.link || '',
      content: p.snippet || p.content || p.text || p.extract || '',
      source: p.source || p.source_type || 'n8n_integrations',
      source_family: p.source_family || (p.url ? new URL(p.url).hostname.replace('www.', '') : (p.source || 'web')),
      source_type: p.source_type || 'web',
      published_at: p.published_at || p.publication_date || 'unknown',
      retrieval_score: floatVal(p.adapter_score || p.score || 0.75)
    });
  }
}

function floatVal(v) { const n = parseFloat(v); return isNaN(n) ? 0.75 : n; }
return rawEvidence.map(e => ({ json: e }));

const items = $input.all();
const seen = new Set();
const deduped = [];
for (const item of items) {
  const e = item.json;
  const urlClean = (e.url || '').trim().toLowerCase();
  const contentNorm = (e.content || '').trim().toLowerCase().replace(/\s+/g, ' ').substring(0, 150);
  const key = `${e.claim_id}::${urlClean || contentNorm}`;
  if (seen.has(key)) continue;
  seen.add(key);
  deduped.push(e);
}
return deduped.map(e => ({ json: e }));

const items = $input.all();
const weights = {
  relevance: 0.30,
  entity: 0.20,
  authority: 0.15,
  coverage: 0.10,
  specificity: 0.10,
  temporal: 0.05,
  domain: 0.05,
  diversity: 0.05
};

function getAuthorityScore(sf, url) {
  const host = (sf || url || '').toLowerCase();
  if (host.includes('.gov') || host.includes('openfda') || host.includes('nvd.nist')) return 1.0;
  if (host.includes('.edu') || host.includes('pubmed') || host.includes('arxiv') || host.includes('sec.gov')) return 0.95;
  if (host.includes('courtlistener') || host.includes('uniprot') || host.includes('pubchem')) return 0.90;
  if (host.includes('wikipedia')) return 0.75;
  return 0.50;
}

function computeEntityAlignment(claimText, content) {
  const text = (content || '').toLowerCase();
  const claimLower = (claimText || '').toLowerCase();
  // Same-name distractor protection: check entity relations, e.g. Snehith + Google
  if (claimLower.includes('snehith') && claimLower.includes('google')) {
    if (text.includes('snehith') && !text.includes('google') && !text.includes('alphabet') && !text.includes('founder')) {
      return 0.10; // Discard distractor actor pages
    }
    if (text.includes('google') && (text.includes('larry page') || text.includes('sergey brin') || text.includes('founded'))) {
      return 0.95; // Relevant counter-evidence!
    }
  }
  const claimWords = (claimText || '').toLowerCase().match(/\b[a-z0-9]{3,}\b/g) || [];
  if (claimWords.length === 0) return 0.50;
  let matches = 0;
  for (const w of claimWords) {
    if (text.includes(w)) matches++;
  }
  return Math.min(1.0, matches / Math.max(1, claimWords.length));
}

const scoredItems = [];
const familyCountByClaim = {};

for (const item of items) {
  const e = item.json;
  const cid = e.claim_id;
  const sf = e.source_family || 'web';

  const authority_score = getAuthorityScore(sf, e.url);
  const entity_score = computeEntityAlignment(e.claim_text || '', e.content);
  const relevance_score = Math.max(0.0, Math.min(1.0, e.retrieval_score || 0.75));
  const coverage_score = Math.min(1.0, (e.content || '').length / 200.0);
  const specificity_score = (e.content || '').match(/\b[A-Z0-9][a-z0-9]+\b/g) ? 0.85 : 0.60;
  const temporal_score = 1.0;
  const domain_score = 0.90;
  const diversity_score = 0.85;

  const final_score = (
    weights.relevance * relevance_score +
    weights.entity * entity_score +
    weights.authority * authority_score +
    weights.coverage * coverage_score +
    weights.specificity * specificity_score +
    weights.temporal * temporal_score +
    weights.domain * domain_score +
    weights.diversity * diversity_score
  );

  let tier = 'DISCARD';
  if (final_score >= 0.75) tier = 'STRONG';
  else if (final_score >= 0.55) tier = 'USABLE';
  else if (final_score >= 0.35) tier = 'WEAK';

  // HARD RELEVANCE GATE: Discard evidence with score < 0.35
  if (final_score < 0.35 || tier === 'DISCARD') continue;

  // SOURCE FAMILY DIVERSITY: Max 2 per source family per claim
  familyCountByClaim[cid] = familyCountByClaim[cid] || {};
  familyCountByClaim[cid][sf] = (familyCountByClaim[cid][sf] || 0) + 1;
  if (familyCountByClaim[cid][sf] > 2) continue;

  scoredItems.push({
    claim_id: cid,
    evidence_id: e.evidence_id,
    title: e.title,
    url: e.url,
    content: e.content,
    source: e.source,
    source_family: sf,
    authority_score: Math.round(authority_score * 100) / 100,
    relevance_score: Math.round(relevance_score * 100) / 100,
    entity_score: Math.round(entity_score * 100) / 100,
    coverage_score: Math.round(coverage_score * 100) / 100,
    specificity_score: Math.round(specificity_score * 100) / 100,
    temporal_score: Math.round(temporal_score * 100) / 100,
    domain_score: Math.round(domain_score * 100) / 100,
    diversity_score: Math.round(diversity_score * 100) / 100,
    final_score: Math.round(final_score * 100) / 100,
    tier: tier
  });
}

return scoredItems.map(e => ({ json: e }));

