const evidenceItems = $input.all().map(i => i.json);

// Group top 3-5 evidence items per claim_id
const evidenceByClaim = {};
for (const e of evidenceItems) {
  const cid = e.claim_id;
  evidenceByClaim[cid] = evidenceByClaim[cid] || [];
  if (evidenceByClaim[cid].length < 5) {
    evidenceByClaim[cid].push(e);
  }
}

const finalClaimsBundle = validClaims.map(c => ({
  claim_id: c.claim_id,
  claim_text: c.claim_text,
  evidence: (evidenceByClaim[c.claim_id] || []).sort((a, b) => b.final_score - a.final_score)
}));

return [{ json: { claims: finalClaimsBundle } }];
